const placeDocPages = `-- name: PlaceDocPages :exec
UPDATE doc_pages d
SET parent_id = $1::uuid, position = array_position($2::uuid[], d.id) - 1,
    updated_at = CASE WHEN d.id = $3::uuid THEN now() ELSE d.updated_at END
WHERE d.id = ANY($2::uuid[])
`

