const saveDocContent = `-- name: SaveDocContent :one
UPDATE doc_pages
SET title = $1, body = $2, version = version + 1,
    updated_by = $3, updated_at = now()
WHERE id = $4 AND version = $5 AND deleted_at IS NULL
RETURNING version
`

type SaveDocContentParams struct {
	Title       string      `json:"title"`
	Body        string      `json:"body"`
	ActorID     pgtype.UUID `json:"actor_id"`
	ID          pgtype.UUID `json:"id"`
	BaseVersion int32       `json:"base_version"`
}

// The next version, if base is still the current one.
func (q *Queries) SaveDocContent(ctx context.Context, arg SaveDocContentParams) (int32, error) {
	row := q.db.QueryRow(ctx, saveDocContent,
		arg.Title,
		arg.Body,
		arg.ActorID,
		arg.ID,
		arg.BaseVersion,
	)
	var version int32
	err := row.Scan(&version)
	return version, err
}

const searchDocs = `-- name: SearchDocs :many
SELECT d.id, d.project_id, p.name AS project_name, d.title,
       left(regexp_replace(d.body, '\s+', ' ', 'g'), 400)::text AS body_start
FROM doc_pages d
JOIN projects p ON p.id = d.project_id
WHERE p.org_id = $1 AND d.deleted_at IS NULL
  AND ($2::uuid IS NULL OR d.project_id = $2::uuid)
  AND ($3::text = '' OR d.search @@ to_tsquery('simple', $3::text))
ORDER BY CASE WHEN $3::text = '' THEN 0 ELSE ts_rank(d.search, to_tsquery('simple', $3::text)) END DESC, d.updated_at DESC
LIMIT $4
`

type SearchDocsParams struct {
	OrgID     pgtype.UUID `json:"org_id"`
	ProjectID pgtype.UUID `json:"project_id"`
	Tsq       string      `json:"tsq"`
	RowLimit  int32       `json:"row_limit"`
}

type SearchDocsRow struct {
	ID          pgtype.UUID `json:"id"`
	ProjectID   pgtype.UUID `json:"project_id"`
	ProjectName string      `json:"project_name"`
	Title       string      `json:"title"`
	BodyStart   string      `json:"body_start"`
}

// ⌘K and the tree's search: titles and text by word prefix, best first.
func (q *Queries) SearchDocs(ctx context.Context, arg SearchDocsParams) ([]SearchDocsRow, error) {
	rows, err := q.db.Query(ctx, searchDocs,
		arg.OrgID,
		arg.ProjectID,
		arg.Tsq,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SearchDocsRow{}
	for rows.Next() {
		var i SearchDocsRow
		if err := rows.Scan(
			&i.ID,
			&i.ProjectID,
			&i.ProjectName,
			&i.Title,
			&i.BodyStart,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

